mapper.select:
select mgr.id, mgr.goods_id,mgr.sell_num,mgr.create_time,mgr.market_id,mgr.discount_rate,mgr.goods_info,sp.`name`,sp.img,sp.sale_price_began,sp.sale_price_end,sp.state,sp.market_price,
       sp.selection_num,mt.market_name,(sp.unit_price - sp.sale_price_began) as max_profit,sp.unit_price, (sp.virtual_sale_num + sp.sale_num) as sale_num
from market_goods_relation mgr,spu sp,market mt

    mgr.goods_id = sp.id
    and mgr.market_id = mt.id

        and mgr.user_id = #{req.userId}


        and mgr.relation_type = #{req.relationType}


        and mgr.market_id = #{req.marketId}


        and mgr.goods_id = #{req.goodsId}


        and sp.`name` like CONCAT('%',#{req.goodsName},'%')


        and sp.`category_id` = #{req.categoryId}


         AND sale_price >= #{req.salePriceL} 


         AND sale_price <= #{req.salePriceR} 


        and sp.`state` = #{req.spuState}


        and mgr.goods_id  in

            #{item}


    and mgr.state = 1


order by mgr.create_time desc

select mgr.id, mgr.goods_id,mgr.sell_num,mgr.create_time,mgr.discount_rate,sp.sale_num,sp.`name`,sp.img,sp.sale_price_began,sp.sale_price_end,sp.state,sp.selection_num,sp.market_price
,sp.max_profit
from market_bind mb,market_goods_relation mgr,spu sp

    mb.market_id = mgr.market_id
    and mgr.goods_id = sp.id
    and mb.user_id = #{req.userId}

        and mb.bind_type = #{req.bindType}


        and mgr.relation_type = #{req.relationType}


        and mb.market_id = #{req.marketId}


        and sp.`name` like CONCAT('%',#{req.goodsName},'%')


        and mgr.goods_id = #{req.goodsId}


        and sp.category_id = #{req.categoryId}




        order by mgr.create_time desc


        order by mgr.create_time asc




        order by sp.sale_price_began desc


        order by sp.sale_price_began asc




        order by sp.max_profit desc


        order by sp.max_profit asc



    order by mgr.create_time desc

    select mgrn.id, mgry.goods_id, mgry.discount_rate, mgry.sell_num as clientSellNum,
    mgry.market_id,
    sp.`name` as goodsName,sp.img as goodsPicture,
    sp.sale_price_end,sp.state,sp.selection_num,sp.unit_price,
    (mgrn.id is not null) as choose,
    sp.create_time as time,


    (sp.virtual_sale_num + sp.sale_num) as sellNum,
    (sp.unit_price - sp.sale_price_began) as maxProfit,
    sp.market_price as marketPrice,
    sp.sale_price_began as salePriceBegan,
    sp.create_time as createTime
from market_bind mb
    inner join market_goods_relation mgry on mb.market_id = mgry.market_id and mgry.relation_type = 2 and mgry.state = 1
    inner join spu sp on mgry.goods_id = sp.id
    left join market_goods_relation mgrn on mgry.goods_id = mgrn.goods_id and mgrn.user_id = #{req.accountId}
    and mgrn.relation_type = 3 and mgrn.state = 1 and mgrn.market_id = #{req.marketId}
where
    mb.user_id = #{req.accountId}
    and mb.market_id = #{req.marketId}
    ${req.buildInSQL('marketIdList','mb.market_id')}
    and mb.state = 1
    and mb.bind_type = 3

        and sp.name like CONCAT('%',#{req.goodsName},'%')


        and mgrn.id is not null


        and sp.category_id = #{req.categoryId}


        and (sp.sale_price_began between #{req.salePriceL} and #{req.salePriceR} or sp.sale_price_end between
        #{req.salePriceL} and #{req.salePriceR})

    ${req.buildBetweenSQL('sp.unit_price','unitPriceL','unitPriceR')}
    ${req.buildBetweenSQL('(sp.unit_price - sp.sale_price_began)','maxProfitL','maxProfitR')}
    ${req.buildBetweenSQL('(sp.virtual_sale_num + sp.sale_num)','sellNumL','sellNumR')}
    ${req.sortSQL}

select mgr.id,mgr.discount_rate,mt.market_type,sp.id as spu_id,sp.`name`,sp.img,sp.sale_price_began,sp.sale_price_end,sp.state as spu_state,sp.unit_price,mgr.goods_info,sp.min_pricing_num
from market_goods_relation mgr,spu sp,market mt

    mgr.goods_id = sp.id
    and mgr.market_id = mt.id
    and mgr.user_id = #{req.userId}
    and mgr.relation_type = #{req.relationType}

        and mgr.market_id = #{req.marketId}


        and sp.`name` like CONCAT('%',#{req.goodsName},'%')


        and sp.`category_id` = #{req.categoryId}


        and sp.`state` = #{req.spuState}


        and mgr.goods_id  in

            #{item}


    and mgr.state = 1

${req.sortSQL}
